content.content:
  1	package agentusage
  2	
  3	// msgKey identifies one message of a session. A message with an id is keyed
  4	// by the id alone; one without is keyed by where it was read.
  5	type msgKey struct {
  6		id   string
  7		file string
  8		off  int64
  9	}
 10	
 11	// entry is the last state seen of one message.
 12	type entry struct {
 13		agent    int
 14		file     string
 15		model    string
 16		tokens   Tokens
 17		stopNull bool
 18	}
 19	
 20	// aggregator folds records into per-agent totals, last line wins per
 21	// message id. Agents must be added in a fixed order (parent, then
 22	// sub-agents by ID); a message seen in several files goes to the last.
 23	type aggregator struct {
 24		agents  []Agent
 25		diag    Diagnostics
 26		entries map[msgKey]*entry
 27		order   []msgKey // first appearance, for stable model order
 28	}
 29	
 30	// newAggregator starts from agents carrying their identity (ID, Main, Type,
 31	// State, SpawnDepth); the counters are filled by add and finish.
 32	func newAggregator(agents []Agent) *aggregator {
 33		return &aggregator{agents: agents, entries: map[msgKey]*entry{}}
 34	}
 35	
 36	// addLine decodes one line of agent agentIdx's file and folds it in,
 37	// counting what is skipped. Synthetic and ignored lines never count.
 38	func (a *aggregator) addLine(agentIdx int, file string, off int64, line []byte) {
 39		r, kind := decodeLine(line)
 40		switch kind {
 41		case kindUsage:
 42			a.add(agentIdx, file, off, r)
 43		case kindNoUsage:
 44			a.diag.NoUsage++
 45		case kindUnreadable:
 46			a.diag.UnreadableLines++
 47		case kindIgnored, kindSynthetic:
 48		}
 49	}
 50	
 51	// add folds one usage record in. file and off identify the line when the
 52	// record has no message id.
 53	func (a *aggregator) add(agentIdx int, file string, off int64, r record) {
 54		key := msgKey{id: r.MessageID}
 55		if r.MessageID == "" {
 56			key = msgKey{file: file, off: off}
 57			a.diag.NoMessageID++
 58		}
 59		e, ok := a.entries[key]
 60		if !ok {
 61			e = &entry{}
 62			a.entries[key] = e
 63			a.order = append(a.order, key)
 64		} else if e.agent != agentIdx || e.file != file {
 65			a.diag.CrossFileDuplicates++
 66		}
 67		*e = entry{agent: agentIdx, file: file, model: r.Model, tokens: r.Usage, stopNull: r.StopNull}
 68	}
 69	
 70	// finish returns the agents with Tokens, Models, Messages and
 71	// PartialMessages computed.
 72	func (a *aggregator) finish() []Agent {
 73		for i := range a.agents {
 74			a.agents[i].Tokens, a.agents[i].Models = Tokens{}, nil
 75			a.agents[i].Messages, a.agents[i].PartialMessages = 0, 0
 76		}
 77		for _, key := range a.order {
 78			e := a.entries[key]
 79			ag := &a.agents[e.agent]
 80			ag.Tokens = ag.Tokens.Add(e.tokens)
 81			ag.Messages++
 82			if e.stopNull {
 83				ag.PartialMessages++
 84			}
 85			ag.addModel(e.model)
 86		}
 87		return a.agents
 88	}
 89	
 90	// addModel appends model unless it is empty or already listed.
 91	func (ag *Agent) addModel(model string) {
 92		if model == "" {
 93			return
 94		}
 95		for _, m := range ag.Models {
 96			if m == model {
 97				return
 98			}
 99		}
100		ag.Models = append(ag.Models, model)
101	}
102	package agentusage
103	
104	// Agent is the usage of one agent of a session: the orchestrator (Main) or a
105	// sub-agent.
106	type Agent struct {
107		ID              string
108		Main            bool
109		Type            string // sub-agent type from its meta file; "" if unknown
110		Models          []string
111		Tokens          Tokens
112		Messages        int // distinct message ids
113		PartialMessages int // messages whose last line has no stop reason
114		State           State
115		SpawnDepth      int
116	}
117	
118	// PartialOutput reports whether some message of the agent was still being
119	// written (no stop reason on its last line), so its output count is a floor.
120	func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }
121	
122	// IssueKind classifies a line that could not be counted.
123	type IssueKind int
124	
125	const (
126		IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
127		IssueOversized                   // longer than MaxLineBytes
128	)
129	
130	// FileIssue locates one skipped line. File is a base name, never a path.
131	type FileIssue struct {
132		File   string
133		Offset int64
134		Kind   IssueKind
135	}
136	
137	// Diagnostics counts what parsing skipped or had to guess.
138	type Diagnostics struct {
139		UnreadableLines     int
140		OversizedLines      int
141		NoUsage             int
142		NoMessageID         int
143		CrossFileDuplicates int
144		MetaMissing         int
145		MetaUnreadable      int
146		TruncatedFiles      []string
147		Files               []FileIssue
148	}
149	
150	// Degraded reports whether anything was skipped or guessed.
151	func (d Diagnostics) Degraded() bool {
152		return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
153			d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
154			d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
155	}
156	
157	// Usage is the parsed usage of one session.
158	type Usage struct {
159		SessionID   string
160		Agents      []Agent
161		Versions    []string
162		Diagnostics Diagnostics
163	}
164	
165	// Total returns the tokens of every agent.
166	func (u Usage) Total() Tokens {
167		var t Tokens
168		for _, a := range u.Agents {
169			t = t.Add(a.Tokens)
170		}
171		return t
172	}
173	// Package agentusage reads coding-agent usage logs. It is pure stdlib and
174	// has no dependency on the UI.
175	package agentusage
176	
177	import "math"
178	
179	// Tokens counts the tokens of one or more agent requests.
180	type Tokens struct {
181		Input      int64
182		Output     int64
183		CacheRead  int64
184		CacheWrite int64
185	}
186	
187	// Total returns the sum of the four counters, saturating at math.MaxInt64.
188	func (t Tokens) Total() int64 {
189		return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
190	}
191	
192	// Add returns the field-wise sum of t and o, each field saturating at
193	// math.MaxInt64.
194	func (t Tokens) Add(o Tokens) Tokens {
195		return Tokens{
196			Input:      satAdd(t.Input, o.Input),
197			Output:     satAdd(t.Output, o.Output),
198			CacheRead:  satAdd(t.CacheRead, o.CacheRead),
199			CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
200		}
201	}
202	
203	// satAdd adds two non-negative counters without wrapping.
204	func satAdd(a, b int64) int64 {
205		if a > math.MaxInt64-b {
206			return math.MaxInt64
207		}
208		return a + b
209	}
210	package agentusage
211	
212	import (
213		"errors"
214		"os"
215	)
216	
217	// errNotPlain is returned when a path is not what Lstat said it was a moment
218	// ago (swapped for a link or another file). It is fixed so it never carries
219	// a path or content.
220	var errNotPlain = errors.New("agentusage: path changed while being opened")
221	
222	// openPlain opens path only if it is not a symbolic link and its mode, as
223	// reported by Lstat, matches wantDir. The opened handle is compared with the
224	// Lstat result (os.SameFile), which closes the window between checking and
225	// opening. A missing path yields an error satisfying os.ErrNotExist; a path
226	// of the wrong kind yields (nil, nil).
227	func openPlain(path string, wantDir bool) (*os.File, error) {
228		li, err := os.Lstat(path)
229		if err != nil {
230			return nil, err
231		}
232		if li.IsDir() != wantDir || (!wantDir && !li.Mode().IsRegular()) {
233			return nil, nil
234		}
235		f, err := os.Open(path)
236		if err != nil {
237			return nil, err
238		}
239		fi, err := f.Stat()
240		if err != nil || !os.SameFile(li, fi) {
241			_ = f.Close()
242			if err == nil {
243				err = errNotPlain
244			}
245			return nil, err
246		}
247		return f, nil
248	}
249	package agentusage
250	
251	import (
252		"encoding/json"
253		"errors"
254		"io"
255	)
256	
257	// State tells whether a sub-agent has finished.
258	type State int
259	
260	const (
261		StateUnknown State = iota
262		StateFinished
263		StateUnfinished
264	)
265	
266	// meta is the subset of agent-<id>.meta.json that is read. The description
267	// and worktree path keys are deliberately absent: they are never decoded.
268	type meta struct {
269		AgentType  string
270		Finished   *bool
271		SpawnDepth int
272	}
273	
274	// wireMeta keeps agentType and spawnDepth raw: one of an unexpected type
275	// costs that field only. finished stays typed, so a wrong type is an error.
276	type wireMeta struct {
277		AgentType  json.RawMessage `json:"agentType"`
278		Finished   *bool           `json:"finished"`
279		SpawnDepth json.RawMessage `json:"spawnDepth"`
280	}
281	
282	// maxMetaBytes is the largest meta file read; a bigger one is refused.
283	const maxMetaBytes = 1 << 20
284	
285	// Fixed messages because encoding/json errors can quote file content.
286	var (
287		errMalformedMeta = errors.New("agentusage: malformed meta file")
288		errMetaTooBig    = errors.New("agentusage: meta file too large")
289		errMetaNotPlain  = errors.New("agentusage: meta file is not a regular file")
290	)
291	
292	// readMeta reads a meta file. A missing file yields an error satisfying
293	// errors.Is(err, os.ErrNotExist). A symbolic link or non-regular file is
294	// refused, and reading is bounded by maxMetaBytes.
295	func readMeta(path string) (meta, error) {
296		f, err := openPlain(path, false)
297		if err != nil {
298			return meta{}, err
299		}
300		if f == nil {
301			return meta{}, errMetaNotPlain
302		}
303		defer func() { _ = f.Close() }()
304		b, err := io.ReadAll(io.LimitReader(f, maxMetaBytes+1))
305		if err != nil {
306			return meta{}, err
307		}
308		if len(b) > maxMetaBytes {
309			return meta{}, errMetaTooBig
310		}
311		var w wireMeta
312		if json.Unmarshal(b, &w) != nil {
313			return meta{}, errMalformedMeta
314		}
315		m := meta{Finished: w.Finished, AgentType: optString(w.AgentType)}
316		if len(w.SpawnDepth) > 0 {
317			_ = json.Unmarshal(w.SpawnDepth, &m.SpawnDepth) // wrong type: stays 0
318		}
319		return m, nil
320	}
321	
322	// state maps the finished flag; absent or null is StateUnknown.
323	func (m meta) state() State {
324		switch {
325		case m.Finished == nil:
326			return StateUnknown
327		case *m.Finished:
328			return StateFinished
329		}
330		return StateUnfinished
331	}
