333	
334	import (
335		"errors"
336		"fmt"
337		"os"
338		"path/filepath"
339		"sort"
340		"strings"
341	)
342	
343	const (
344		transcriptExt = ".jsonl"
345		metaExt       = ".meta.json"
346		agentPrefix   = "agent-"
347		subagentsDir  = "subagents"
348	)
349	
350	// SubAgentFiles locates one sub-agent's files; Meta is "" if absent.
351	type SubAgentFiles struct{ ID, Transcript, Meta string }
352	
353	// SessionFiles locates a session's transcripts.
354	type SessionFiles struct {
355		ID, Parent string
356		SubAgents  []SubAgentFiles
357	}
358	
359	// ProjectsRoot returns the Claude Code projects directory:
360	// $CLAUDE_CONFIG_DIR/projects, else ~/.claude/projects.
361	func ProjectsRoot() (string, error) {
362		if dir := os.Getenv("CLAUDE_CONFIG_DIR"); dir != "" {
363			return filepath.Join(dir, "projects"), nil
364		}
365		home, err := os.UserHomeDir()
366		if err != nil {
367			return "", err
368		}
369		return filepath.Join(home, ".claude", "projects"), nil
370	}
371	
372	// LocateSession finds the sub-agent files of the session whose parent
373	// transcript is <dir>/<uuid>.jsonl, looking in <dir>/<uuid>/subagents/. A
374	// missing session directory means no sub-agents. Symbolic links are ignored
375	// and nothing is searched recursively.
376	func LocateSession(parentTranscript string) (SessionFiles, error) {
377		base := filepath.Base(parentTranscript)
378		if !strings.HasSuffix(base, transcriptExt) {
379			return SessionFiles{}, fmt.Errorf("agentusage: %s does not end in %s", base, transcriptExt)
380		}
381		info, err := os.Lstat(parentTranscript)
382		if err != nil {
383			return SessionFiles{}, err
384		}
385		if !info.Mode().IsRegular() {
386			return SessionFiles{}, fmt.Errorf("agentusage: %s is not a regular file", parentTranscript)
387		}
388		id := strings.TrimSuffix(base, transcriptExt)
389		files := SessionFiles{ID: id, Parent: parentTranscript}
390		sessionDir := filepath.Join(filepath.Dir(parentTranscript), id)
391		if fi, err := os.Lstat(sessionDir); err != nil || !fi.IsDir() {
392			if err == nil || errors.Is(err, os.ErrNotExist) {
393				return files, nil // absent, or a link: no sub-agents
394			}
395			return files, err
396		}
397		files.SubAgents, err = subAgentFiles(filepath.Join(sessionDir, subagentsDir))
398		return files, err
399	}
400	
401	// subAgentFiles lists agent-<id>.jsonl files directly inside dir, sorted by
402	// ID, each with its meta file if one exists. A missing dir or a symbolic
403	// link yields nothing.
404	func subAgentFiles(dir string) ([]SubAgentFiles, error) {
405		f, err := openPlain(dir, true)
406		if f == nil {
407			if err == nil || errors.Is(err, os.ErrNotExist) {
408				return nil, nil
409			}
410			return nil, err
411		}
412		defer func() { _ = f.Close() }()
413		entries, err := f.ReadDir(-1)
414		if err != nil {
415			return nil, err
416		}
417		var out []SubAgentFiles
418		for _, e := range entries {
419			if sa, ok := subAgentEntry(dir, e); ok {
420				out = append(out, sa)
421			}
422		}
423		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
424		return out, nil
425	}
426	
427	// subAgentEntry turns a directory entry into a sub-agent, if it is a
428	// regular agent-<id>.jsonl file.
429	func subAgentEntry(dir string, e os.DirEntry) (SubAgentFiles, bool) {
430		name := e.Name()
431		if !e.Type().IsRegular() || !strings.HasPrefix(name, agentPrefix) || !strings.HasSuffix(name, transcriptExt) {
432			return SubAgentFiles{}, false
433		}
434		id := strings.TrimSuffix(strings.TrimPrefix(name, agentPrefix), transcriptExt)
435		if id == "" {
436			return SubAgentFiles{}, false
437		}
438		sa := SubAgentFiles{ID: id, Transcript: filepath.Join(dir, name)}
439		metaPath := filepath.Join(dir, agentPrefix+id+metaExt)
440		if mf, _ := openPlain(metaPath, false); mf != nil {
441			_ = mf.Close()
442			sa.Meta = metaPath
443		}
444		return sa, true
445	}

