 90	// addModel appends model unless it is empty or already listed.
 91	func (ag *Agent) addModel(model string) {
 92		if model == "" {
 93			return
 94		}
 95		for _, m := range ag.Models {
 96			if m == model {
 97				return
 98			}
 99		}
100		ag.Models = append(ag.Models, model)
101	}
