212	import (
213		"errors"
214		"os"
215	)
216	
217	// errNotPlain is returned when a path is not what Lstat said it was a moment
218	// ago (swapped for a link or another file). It is fixed so it never carries
219	// a path or content.
220	var errNotPlain = errors.New("agentusage: path changed while being opened")
221	
222	// openPlain opens path only if it is not a symbolic link and its mode, as
223	// reported by Lstat, matches wantDir. The opened handle is compared with the
224	// Lstat result (os.SameFile), which closes the window between checking and
225	// opening. A missing path yields an error satisfying os.ErrNotExist; a path
226	// of the wrong kind yields (nil, nil).
227	func openPlain(path string, wantDir bool) (*os.File, error) {
228		li, err := os.Lstat(path)
229		if err != nil {
230			return nil, err
231		}
232		if li.IsDir() != wantDir || (!wantDir && !li.Mode().IsRegular()) {
233			return nil, nil
234		}
235		f, err := os.Open(path)
236		if err != nil {
237			return nil, err
238		}
239		fi, err := f.Stat()
240		if err != nil || !os.SameFile(li, fi) {
241			_ = f.Close()
242			if err == nil {
243				err = errNotPlain
244			}
245			return nil, err
246		}
247		return f, nil
248	}
