258	type State int
259	
260	const (
261		StateUnknown State = iota
262		StateFinished
263		StateUnfinished
264	)
265	
266	// meta is the subset of agent-<id>.meta.json that is read. The description
267	// and worktree path keys are deliberately absent: they are never decoded.
268	type meta struct {
269		AgentType  string
270		Finished   *bool
271		SpawnDepth int
272	}
273	
274	// wireMeta keeps agentType and spawnDepth raw: one of an unexpected type
275	// costs that field only. finished stays typed, so a wrong type is an error.
276	type wireMeta struct {
277		AgentType  json.RawMessage `json:"agentType"`
278		Finished   *bool           `json:"finished"`
279		SpawnDepth json.RawMessage `json:"spawnDepth"`
280	}
281	
282	// maxMetaBytes is the largest meta file read; a bigger one is refused.
283	const maxMetaBytes = 1 << 20
284	
285	// Fixed messages because encoding/json errors can quote file content.
286	var (
287		errMalformedMeta = errors.New("agentusage: malformed meta file")
288		errMetaTooBig    = errors.New("agentusage: meta file too large")
289		errMetaNotPlain  = errors.New("agentusage: meta file is not a regular file")
290	)
291	
292	// readMeta reads a meta file. A missing file yields an error satisfying
293	// errors.Is(err, os.ErrNotExist). A symbolic link or non-regular file is
294	// refused, and reading is bounded by maxMetaBytes.
295	func readMeta(path string) (meta, error) {
296		f, err := openPlain(path, false)
297		if err != nil {
298			return meta{}, err
299		}
300		if f == nil {
301			return meta{}, errMetaNotPlain
302		}
303		defer func() { _ = f.Close() }()
304		b, err := io.ReadAll(io.LimitReader(f, maxMetaBytes+1))
305		if err != nil {
306			return meta{}, err
307		}
308		if len(b) > maxMetaBytes {
309			return meta{}, errMetaTooBig
310		}
311		var w wireMeta
312		if json.Unmarshal(b, &w) != nil {
313			return meta{}, errMalformedMeta
314		}
315		m := meta{Finished: w.Finished, AgentType: optString(w.AgentType)}
316		if len(w.SpawnDepth) > 0 {
317			_ = json.Unmarshal(w.SpawnDepth, &m.SpawnDepth) // wrong type: stays 0
318		}
319		return m, nil
320	}
321	
