func TestReadMetaInvalid(t *testing.T) {
	for name, content := range map[string]string{
		"not json":   `hello ` + sentinel,
		"truncated":  `{"agentType":"` + sentinel,
		"empty":      ``,
		"wrong type": `{"finished":"` + sentinel + `"}`,
	} {
		t.Run(name, func(t *testing.T) {
			p := filepath.Join(t.TempDir(), "m.json")
			writeFile(t, p, content)
			_, err := readMeta(p)
			if err == nil {
				t.Fatal("want an error")
			}
			if strings.Contains(err.Error(), sentinel) {
				t.Fatalf("error leaks file content: %v", err)
			}
		})
	}
}

func TestReadMetaMissingFile(t *testing.T) {
	_, err := readMeta(filepath.Join(t.TempDir(), "absent.meta.json"))
	if !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("err = %v, want errors.Is os.ErrNotExist", err)
	}
}

func TestReadMetaNeverReadsDescriptionOrWorktree(t *testing.T) {
	p := filepath.Join(t.TempDir(), "m.json")
	writeFile(t, p, `{"agentType":"coder","finished":true,"spawnDepth":1,`+
		`"description":"`+sentinel+`","worktreePath":"/x/`+sentinel+`"}`)
	got, err := readMeta(p)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(got.AgentType, sentinel) {
		t.Fatalf("sentinel leaked: %+v", got)
	}
	// Even a wrongly typed description must not matter: it is never decoded.
	writeFile(t, p, `{"agentType":"coder","description":{"a":"`+sentinel+`"},"worktreePath":[1]}`)
	if _, err := readMeta(p); err != nil {
		t.Fatalf("undeclared fields of any type must be skipped: %v", err)
	}
}

// An unexpected type for agentType or spawnDepth costs that field only.
func TestReadMetaTolerantTypes(t *testing.T) {
	for name, content := range map[string]string{
		"agentType number":    `{"agentType":5,"finished":true,"spawnDepth":2}`,
		"agentType object":    `{"agentType":{"a":"` + sentinel + `"},"finished":true,"spawnDepth":2}`,
		"spawnDepth string":   `{"agentType":"coder","finished":true,"spawnDepth":"2"}`,
		"spawnDepth fraction": `{"agentType":"coder","finished":true,"spawnDepth":1.5}`,
		"both wrong":          `{"agentType":[1],"finished":true,"spawnDepth":null}`,
	} {
		t.Run(name, func(t *testing.T) {
			p := filepath.Join(t.TempDir(), "m.json")
			writeFile(t, p, content)
			got, err := readMeta(p)
			if err != nil {
				t.Fatalf("readMeta: %v", err)
			}
			if got.state() != StateFinished {
				t.Fatalf("state = %d, want finished kept", got.state())
			}
			if got.SpawnDepth != 0 && name != "agentType number" && name != "agentType object" {
				t.Fatalf("SpawnDepth = %d, want 0", got.SpawnDepth)
			}
			if strings.HasPrefix(name, "agentType") && got.AgentType != "" {
				t.Fatalf("AgentType = %q, want empty", got.AgentType)
			}
		})
	}
}

func TestReadMetaSizeLimit(t *testing.T) {
	pad := func(n int) string {
		base := `{"agentType":"coder","finished":true,"x":"`
		return base + strings.Repeat("a", n-len(base)-2) + `"}`
	}
	t.Run("exactly the limit is read", func(t *testing.T) {
		p := filepath.Join(t.TempDir(), "m.json")
		writeFile(t, p, pad(maxMetaBytes))
		if _, err := readMeta(p); err != nil {
			t.Fatalf("readMeta: %v", err)
		}
	})
	t.Run("over the limit is refused without content", func(t *testing.T) {
		p := filepath.Join(t.TempDir(), "m.json")
		content := pad(maxMetaBytes + 1)
		content = strings.Replace(content, `"x":"`, `"x":"`+sentinel, 1)
		writeFile(t, p, content)
		_, err := readMeta(p)
		if err == nil {
			t.Fatal("want an error")
		}
		if strings.Contains(err.Error(), sentinel) {
			t.Fatalf("error leaks file content: %v", err)
		}
	})
}
	}
}

func TestLocateSessionIgnoresSymlinks(t *testing.T) {
	isolateEnv(t)
	parent, dir := session(t)
	sub := filepath.Join(dir, "subagents")
	target := filepath.Join(t.TempDir(), "real.jsonl")
	writeFile(t, target, "{}\n")
	writeFile(t, filepath.Join(sub, "agent-real.jsonl"), "{}\n")
	writeFile(t, filepath.Join(sub, "agent-real.meta.json"), "{}")
	if err := os.Symlink(target, filepath.Join(sub, "agent-link.jsonl")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	// A symlinked meta must not be picked up either.
	metaTarget := filepath.Join(t.TempDir(), "m.json")
	writeFile(t, metaTarget, "{}")
	writeFile(t, filepath.Join(sub, "agent-lm.jsonl"), "{}\n")
	if err := os.Symlink(metaTarget, filepath.Join(sub, "agent-lm.meta.json")); err != nil {
		t.Fatal(err)
	}

	got, err := LocateSession(parent)
	if err != nil {
		t.Fatal(err)
	}
	ids := map[string]SubAgentFiles{}
	for _, s := range got.SubAgents {
		ids[s.ID] = s
	}
	if _, ok := ids["link"]; ok {
		t.Fatalf("symlinked transcript must be ignored: %+v", got.SubAgents)
	}
	if len(got.SubAgents) != 2 || ids["real"].Meta == "" {
		t.Fatalf("got %+v", got.SubAgents)
	}
	if ids["lm"].Meta != "" {
		t.Fatalf("symlinked meta must be ignored: %+v", ids["lm"])
	}
}

func TestLocateSessionSymlinkedSubagentsDirIgnored(t *testing.T) {
	isolateEnv(t)
	parent, dir := session(t)
	other := t.TempDir()
	writeFile(t, filepath.Join(other, "agent-q.jsonl"), "{}\n")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(other, filepath.Join(dir, "subagents")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	got, err := LocateSession(parent)
	if err != nil || len(got.SubAgents) != 0 {
		t.Fatalf("got %+v, err %v", got, err)
	}
}

func TestLocateSessionParentWithoutJSONLSuffix(t *testing.T) {
	isolateEnv(t)
	for _, name := range []string{sessUUID, sessUUID + ".json", sessUUID + ".txt"} {
		t.Run(name, func(t *testing.T) {
			p := filepath.Join(t.TempDir(), name)
			writeFile(t, p, "{}\n")
			_, err := LocateSession(p)
			if err == nil {
				t.Fatal("want an error for a parent without the .jsonl suffix")
			}
			// Today the error is an accidental ENOTDIR from probing
			// "<name>/subagents" under a regular file; the check must be
			// explicit, not a side effect.
			if errors.Is(err, syscall.ENOTDIR) {
				t.Fatalf("error is an accidental ENOTDIR, want an explicit suffix check: %v", err)
			}
		})
	}
}

